// ENG-2227 live proof: drives real input on a scratch canvas, then deletes it.
const TITLE = `Canvas/ENG-2227 link proof ${Date.now()}`;
const FIRST_URL = "https://example.com/eng-2227-first";
const EDITED_URL = "https://example.com/eng-2227-edited";

const shot = (page, outDir, name) =>
  page.screenshot({ path: `${outDir}/eng2227-${name}.png` });

const readPersistedUrl = (page, uid) =>
  page.evaluate((uid) => {
    const [[p]] = window.roamAlphaAPI.data.q(
      "[:find (pull ?p [:block/props]) :in $ ?uid :where [?p :block/uid ?uid]]",
      uid,
    );
    const store = p?.[":block/props"]?.["roamjs-query-builder"]?.tldraw?.store;
    const text = Object.values(store ?? {}).find(
      (r) => r?.typeName === "shape" && r?.type === "text",
    );
    return { hasText: Boolean(text), url: text?.meta?.url ?? null };
  }, uid);

const iconState = (page) =>
  page.evaluate(() => {
    const anchor = document.querySelector(".tl-canvas ~ * .tl-hyperlink-button, .tl-hyperlink-button");
    const text = document.querySelector('.tl-shape[data-shape-type="text"]');
    if (!anchor) return { present: false };
    const a = anchor.getBoundingClientRect();
    const t = text?.getBoundingClientRect();
    return {
      present: true,
      href: anchor.getAttribute("href"),
      hidden: anchor.classList.contains("tl-hyperlink-button__hidden"),
      clearOfText: t ? a.left >= t.right - 1 : null,
      verticalOffset: t ? Math.round(a.top + a.height / 2 - (t.top + t.height / 2)) : null,
    };
  });

const openEditLink = async (page) => {
  const shape = page.locator('.tl-shape[data-shape-type="text"]').first();
  const b = await shape.boundingBox();
  await page.mouse.click(b.x + b.width / 2, b.y + b.height / 2, { button: "right" });
  await page.locator('[data-testid="context-menu-sub-trigger.edit"]').hover();
  const item = page.locator('[data-testid="context-menu.edit-link"]');
  const offered = await item.isVisible({ timeout: 3000 }).catch(() => false);
  if (offered) await item.click();
  return offered;
};

const submitUrl = async (page, url) => {
  const input = page.locator(".tlui-edit-link-dialog__input");
  await input.waitFor({ timeout: 5000 });
  await input.fill(url);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(800);
};

const openCanvas = async (page, uid) => {
  await page.evaluate((uid) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } }), uid);
  await page.waitForSelector(".tl-canvas", { timeout: 30000 });
  await page.waitForTimeout(2500);
};

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamAlphaAPI));
  },

  async run({ page, context, outDir }) {
    const r = { title: TITLE };
    r.uid = await page.evaluate(async (title) => {
      const uid = window.roamAlphaAPI.util.generateUID();
      await window.roamAlphaAPI.data.page.create({ page: { title, uid } });
      return uid;
    }, TITLE);
    await openCanvas(page, r.uid);

    // 1. text shape from the toolbar
    await page.locator('[data-testid="tools.text"]').click();
    const c = await page.locator(".tl-canvas").first().boundingBox();
    await page.mouse.click(c.x + c.width * 0.35, c.y + c.height * 0.45);
    await page.keyboard.type("a new text to link");
    await page.keyboard.press("Escape");
    await page.waitForTimeout(600);

    // 2. first link on a shape that has never had one (the 2228 bootstrap case)
    r.editLinkOfferedOnFreshShape = await openEditLink(page);
    if (!r.editLinkOfferedOnFreshShape) {
      await shot(page, outDir, "FAIL-no-edit-link");
      return r;
    }
    await submitUrl(page, FIRST_URL);
    r.afterAdd = await iconState(page);
    await page.mouse.click(c.x + 20, c.y + c.height - 20); // deselect
    await page.waitForTimeout(500);
    await shot(page, outDir, "1-after-add");

    // 3. open: icon click opens the target in a new tab
    const [popup] = await Promise.all([
      context.waitForEvent("page", { timeout: 8000 }).catch(() => null),
      page.locator(".tl-hyperlink-button").first().click(),
    ]);
    r.openedUrl = popup ? popup.url() : null;
    if (popup) await popup.close();

    // 4. persisted to Roam, then survives close and reopen
    await page.waitForTimeout(2000);
    r.persistedAfterAdd = await readPersistedUrl(page, r.uid);
    await page.reload();
    await page.waitForFunction(() => Boolean(window.roamjs?.extension?.queryBuilder), null, { timeout: 60000 });
    await openCanvas(page, r.uid);
    r.afterReload = await iconState(page);
    await shot(page, outDir, "2-after-reload");

    // 5. edit
    r.editLinkOfferedWithLink = await openEditLink(page);
    if (r.editLinkOfferedWithLink) await submitUrl(page, EDITED_URL);
    await page.waitForTimeout(2000);
    r.afterEdit = await iconState(page);
    r.persistedAfterEdit = await readPersistedUrl(page, r.uid);

    // 6. remove: an invalid value turns Save into Clear
    if (await openEditLink(page)) {
      await page.locator(".tlui-edit-link-dialog__input").fill("");
      await page.getByRole("button", { name: "Clear" }).click();
      await page.waitForTimeout(2000);
    }
    r.afterRemove = await iconState(page);
    r.persistedAfterRemove = await readPersistedUrl(page, r.uid);
    await shot(page, outDir, "3-after-remove");
    return r;
  },

  async cleanup({ page, state }) {
    const uid = state?.uid;
    if (!uid) return { deleted: false };
    await page.evaluate((uid) => window.roamAlphaAPI.data.page.delete({ page: { uid } }), uid);
    return { deleted: true, uid };
  },
};
